question.globalextra:
public class Tier {
    private String name;
    private int alter;

    public Tier(String name, int alter) {
        this.name = name;
        this.alter = alter;
    }

    public String getName()  { return name; }
    public int    getAlter() { return alter; }

    @Override
    public String toString() {
        return "Tier: " + name + ", Alter: " + alter;
    }
}

question.template:
import os

# ── Tier.java (Basisklasse) ───────────────────────────────────────────────────
tier_code = '''public class Tier {
    private String name;
    private int alter;
    public Tier(String name, int alter) {
        this.name = name;
        this.alter = alter;
    }
    public String getName()  { return name; }
    public int getAlter() { return alter; }
    @Override
    public String toString() {
        return "Tier: " + name + ", Alter: " + alter;
    }
}'''
with open('Tier.java', 'w') as f:
    f.write(tier_code)

# ── Hund.java (Studenten-Code) ────────────────────────────────────────────────
student_answer = """{{ STUDENT_ANSWER | e('py') }}"""
with open('Hund.java', 'w') as f:
    f.write(student_answer)

# ── Test.java (Testfall) ──────────────────────────────────────────────────────
testcode = """{{ TEST.testcode | e('py') }}"""
test_class = '''public class Test {
    public static void main(String[] args) throws Exception {
        ''' + testcode + '''
    }
}'''
with open('Test.java', 'w') as f:
    f.write(test_class)

# ── Kompilierung ───────────────────────────────────────────────────────────────
ret = os.system('javac -encoding UTF-8 Tier.java Hund.java Test.java 2>&1')
if ret == 0:
    os.system('java -Xmx128m -XX:CompressedClassSpaceSize=64m -cp . Test')

question.answer:
public class Hund extends Tier {
    private String rasse;

    public Hund(String name, int alter, String rasse) {
        super(name, alter);
        this.rasse = rasse;
    }

    public String getRasse() {
        return rasse;
    }

    @Override
    public String toString() {
        return "Hund: " + getName() + ", Alter: " + getAlter() + ", Rasse: " + rasse;
    }
}
